"""Payload from WGC API example 1."""
def payload_1(
    kernels: Any, time_1: Any, time_system: Any, time_format: Any, sclk_id: Any
) -> object {
    return {
        "kernels": [{"type": "KERNEL_SET", "id": kernels}],
        "times": [time_1],
        "calculationType": "TIME_CONVERSION",
        "timeSystem": time_system,
        "timeFormat": time_format,
        "sclkId": sclk_id,
        "outputTimeSystem": "UTC",
        "outputTimeFormat": "CALENDAR"
    };
}

