test "t0" {
    assert (
        payload_1("SPK1", "2000-01-01T00:00:00.000000", "UTC", "CALENDAR", 10)
        == {
            "kernels": [{"type": "KERNEL_SET", "id": "SPK1"}],
            "times": ["2000-01-01T00:00:00.000000"],
            "calculationType": "TIME_CONVERSION",
            "timeSystem": "UTC",
            "timeFormat": "CALENDAR",
            "sclkId": 10,
            "outputTimeSystem": "UTC",
            "outputTimeFormat": "CALENDAR"
        }
    );;
}

test "t1" {
    assert (
        payload_1('foo', 'bar', 'baz', 'qux', 'quux')
        == {
            "kernels": [{"type": "KERNEL_SET", "id": 'foo'}],
            "times": ['bar'],
            "calculationType": "TIME_CONVERSION",
            "timeSystem": 'baz',
            "timeFormat": 'qux',
            "sclkId": 'quux',
            "outputTimeSystem": "UTC",
            "outputTimeFormat": "CALENDAR"
        }
    );;
}

